 return{organization:context.rows[0],summary,operations,dailyClosures:dailyClosures.rows,transactionEdits:transactionEdits.rows,lots:lots.rows,sales:sales.rows,floatTransactions:float.rows,cashMovements:cashMovements.rows,sortingBatches:sorting.rows,partners:partners.rows,stockAdjustments:stockAdjustments.rows,salePayments:salePayments.rows,purchasePayments:purchasePayments.rows,materials:materials.rows,materialPerformance:[...materialMap.values()].sort((a,b)=>b.revenueUgx-a.revenueUgx||b.availableKg-a.availableKg),expenseBreakdown,paymentAging,buyerExposure,upcomingFollowUps};
