export async function createMaterial(org:string,user:string,d:any){return(await dbPool.query(`INSERT INTO recycling_material_catalog(organization_id,name,category,created_by)VALUES($1,$2,$3,$4)RETURNING *`,[org,d.name,d.category,user])).rows[0]}
export async function setMaterialState(org:string,id:string,active:boolean){return(await dbPool.query(`UPDATE recycling_material_catalog SET active=$3,updated_at=now() WHERE id=$1::uuid AND organization_id=$2::uuid RETURNING *`,[id,org,active])).rows[0]??null}
export async function markPurchasePaid(org:string,user:string,id:string,d:any,fromFloat=false){const c=await dbPool.connect();try{await c.query('BEGIN');await c.query('SELECT pg_advisory_xact_lock(hashtext($1))',[`recycling-purchase:${id}`]);const lot=(await c.query(`SELECT l.*,(ROUND(l.quantity_kg*l.unit_purchase_price_ugx)+l.worker_wages_ugx+l.food_ugx+l.transport_ugx+l.driver_fee_ugx+l.other_expense_ugx-COALESCE((SELECT SUM(amount_ugx) FROM recycling_purchase_payments WHERE lot_id=l.id),0))::bigint balance FROM recycling_material_lots l WHERE l.id=$1::uuid AND l.organization_id=$2::uuid AND l.origin='purchase' AND l.purchase_payment_status IN('credit','partially_paid') FOR UPDATE`,[id,org])).rows[0];if(!lot||d.amountUgx>Number(lot.balance)||d.paymentReceivedOn<lot.collected_on){await c.query('ROLLBACK');return null}if(fromFloat){await c.query('SELECT pg_advisory_xact_lock(hashtext($1))',[`recycling-finance:${org}`]);const balance=Number((await c.query(`SELECT COALESCE(SUM(CASE WHEN transaction_type='given' THEN amount_ugx ELSE -amount_ugx END),0)::bigint balance FROM recycling_manager_float_transactions WHERE organization_id=$1::uuid`,[org])).rows[0].balance);if(d.amountUgx>balance)throw financeError(`Only ${Math.max(balance,0).toLocaleString()} UGX is left in the manager float. Ask the office to issue more float before paying this supplier.`);await c.query(`UPDATE recycling_material_lots SET manager_float_used_ugx=manager_float_used_ugx+$3 WHERE id=$1::uuid AND organization_id=$2::uuid`,[id,org,d.amountUgx]);await c.query(`INSERT INTO recycling_manager_float_transactions(organization_id,transaction_date,transaction_type,amount_ugx,reference,notes,purchase_lot_id,recorded_by)VALUES($1,$2,'spent',$3,$4,$5,$6,$7)`,[org,d.paymentReceivedOn,d.amountUgx,`SUPPLIER-${d.paymentReference}`,`Supplier payment: ${lot.source_name}`,id,user])}await c.query(`INSERT INTO recycling_purchase_payments(organization_id,lot_id,amount_ugx,paid_on,reference,recorded_by)VALUES($1,$2,$3,$4,$5,$6)`,[org,id,d.amountUgx,d.paymentReceivedOn,d.paymentReference,user]);const status=d.amountUgx===Number(lot.balance)?'paid':'partially_paid';const result=(await c.query(`UPDATE recycling_material_lots SET purchase_payment_status=$3,purchase_paid_on=CASE WHEN $3='paid' THEN $4::date ELSE purchase_paid_on END,purchase_payment_reference=$5,updated_at=now() WHERE id=$1::uuid AND organization_id=$2::uuid RETURNING *`,[id,org,status,d.paymentReceivedOn,d.paymentReference])).rows[0];await c.query('COMMIT');return result}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}
export async function markSalePaid(org:string,user:string,id:string,d:any){const c=await dbPool.connect();try{await c.query('BEGIN');await c.query('SELECT pg_advisory_xact_lock(hashtext($1))',[`recycling-sale:${id}`]);const sale=(await c.query(`SELECT s.*,(ROUND(s.quantity_kg*s.unit_price_ugx)-COALESCE((SELECT SUM(amount_ugx) FROM recycling_sale_payments WHERE sale_id=s.id),0))::bigint balance FROM recycling_material_sales s WHERE s.id=$1::uuid AND s.organization_id=$2::uuid AND s.status IN('recorded','partially_paid') FOR UPDATE`,[id,org])).rows[0];if(!sale||d.amountUgx>Number(sale.balance)||d.paymentReceivedOn<sale.sold_on){await c.query('ROLLBACK');return null}await c.query(`INSERT INTO recycling_sale_payments(organization_id,sale_id,amount_ugx,paid_on,reference,recorded_by)VALUES($1,$2,$3,$4,$5,$6)`,[org,id,d.amountUgx,d.paymentReceivedOn,d.paymentReference,user]);const status=d.amountUgx===Number(sale.balance)?'paid':'partially_paid';const result=(await c.query(`UPDATE recycling_material_sales SET status=$3,paid_on=CASE WHEN $3='paid' THEN $4::date ELSE paid_on END,payment_reference=$5 WHERE id=$1::uuid AND organization_id=$2::uuid RETURNING *`,[id,org,status,d.paymentReceivedOn,d.paymentReference])).rows[0];await c.query('COMMIT');return result}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}

export async function setPurchaseDueDate(org:string,id:string,dueOn:string){return(await dbPool.query(`UPDATE recycling_material_lots SET purchase_due_on=$3::date,updated_at=now() WHERE id=$1::uuid AND organization_id=$2::uuid AND origin='purchase' AND purchase_payment_status IN('credit','partially_paid') AND $3::date>=collected_on RETURNING *`,[id,org,dueOn])).rows[0]??null}
export async function setSaleDueDate(org:string,id:string,dueOn:string){return(await dbPool.query(`UPDATE recycling_material_sales SET due_on=$3::date WHERE id=$1::uuid AND organization_id=$2::uuid AND status IN('recorded','partially_paid') AND $3::date>=sold_on RETURNING *`,[id,org,dueOn])).rows[0]??null}
export async function createPaymentFollowUp(org:string,user:string,id:string,d:any){return(await dbPool.query(`INSERT INTO recycling_payment_followups(organization_id,sale_id,contact_method,outcome,note,next_follow_up_on,recorded_by) SELECT $2::uuid,s.id,$3,$4,$5,$6::date,$7::uuid FROM recycling_material_sales s WHERE s.id=$1::uuid AND s.organization_id=$2::uuid AND s.status IN('recorded','partially_paid') RETURNING *`,[id,org,d.contactMethod,d.outcome,d.note,d.nextFollowUpOn??null,user])).rows[0]??null}

export async function closeRecyclingDay(org:string,user:string,d:any){
 const c=await dbPool.connect();
 try{
  await c.query('BEGIN');
  await c.query('SELECT pg_advisory_xact_lock(hashtext($1))',[`recycling-close:${org}:${d.operatingDate}`]);
  const context=(await c.query(`SELECT type,CURRENT_DATE::text today FROM organizations WHERE id=$1::uuid`,[org])).rows[0];
  if(!context||context.type!=='recycling_company')throw Object.assign(new Error('This workspace is not registered as a recycling company'),{statusCode:403});
  if(d.operatingDate>String(context.today).slice(0,10))throw Object.assign(new Error('A future business day cannot be closed'),{statusCode:400});
  if((await c.query(`SELECT 1 FROM recycling_daily_closures WHERE organization_id=$1::uuid AND operating_date=$2::date AND status='closed'`,[org,d.operatingDate])).rowCount)throw financeError(`Business day ${d.operatingDate} is already closed`);
  const snapshot=(await c.query(`SELECT jsonb_build_object(
   'purchaseCount',(SELECT COUNT(*) FROM recycling_material_lots WHERE organization_id=$1::uuid AND origin='purchase' AND collected_on=$2::date),
   'purchasedKg',COALESCE((SELECT SUM(quantity_kg) FROM recycling_material_lots WHERE organization_id=$1::uuid AND origin='purchase' AND collected_on=$2::date),0),
   'purchaseCostUgx',COALESCE((SELECT SUM(ROUND(quantity_kg*unit_purchase_price_ugx)+worker_wages_ugx+food_ugx+transport_ugx+driver_fee_ugx+other_expense_ugx) FROM recycling_material_lots WHERE organization_id=$1::uuid AND origin='purchase' AND collected_on=$2::date),0),
   'sortingCount',(SELECT COUNT(*) FROM recycling_sorting_batches WHERE organization_id=$1::uuid AND processed_on=$2::date),
   'sortedOutputKg',COALESCE((SELECT SUM(output_kg) FROM recycling_sorting_batches WHERE organization_id=$1::uuid AND processed_on=$2::date),0),
   'processingCostUgx',COALESCE((SELECT SUM(processing_cost_ugx) FROM recycling_sorting_batches WHERE organization_id=$1::uuid AND processed_on=$2::date),0),
   'saleCount',(SELECT COUNT(*) FROM recycling_material_sales WHERE organization_id=$1::uuid AND sold_on=$2::date),
   'soldKg',COALESCE((SELECT SUM(quantity_kg) FROM recycling_material_sales WHERE organization_id=$1::uuid AND sold_on=$2::date),0),
   'salesValueUgx',COALESCE((SELECT SUM(quantity_kg*unit_price_ugx) FROM recycling_material_sales WHERE organization_id=$1::uuid AND sold_on=$2::date),0),
   'cashReceivedUgx',COALESCE((SELECT SUM(amount_ugx) FROM recycling_sale_payments WHERE organization_id=$1::uuid AND paid_on=$2::date),0),
   'supplierPaymentsUgx',COALESCE((SELECT SUM(amount_ugx) FROM recycling_purchase_payments WHERE organization_id=$1::uuid AND paid_on=$2::date),0),
   'floatGivenUgx',COALESCE((SELECT SUM(amount_ugx) FROM recycling_manager_float_transactions WHERE organization_id=$1::uuid AND transaction_date=$2::date AND transaction_type='given'),0),
   'floatSpentUgx',COALESCE((SELECT SUM(amount_ugx) FROM recycling_manager_float_transactions WHERE organization_id=$1::uuid AND transaction_date=$2::date AND transaction_type='spent'),0),
   'stockOnHandKg',COALESCE((SELECT SUM(available_kg) FROM recycling_material_lots WHERE organization_id=$1::uuid),0)
  ) snapshot`,[org,d.operatingDate])).rows[0].snapshot;
  const result=(await c.query(`INSERT INTO recycling_daily_closures(organization_id,operating_date,status,snapshot,notes,closed_by) VALUES($1,$2,'closed',$3::jsonb,$4,$5) ON CONFLICT(organization_id,operating_date) DO UPDATE SET status='closed',snapshot=EXCLUDED.snapshot,notes=EXCLUDED.notes,closed_by=EXCLUDED.closed_by,closed_at=now(),reopened_by=NULL,reopened_at=NULL,reopen_reason=NULL,updated_at=now() RETURNING *`,[org,d.operatingDate,JSON.stringify(snapshot),d.notes??null,user])).rows[0];
  await c.query('COMMIT');return result;
 }catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}
}

export async function reopenRecyclingDay(org:string,user:string,id:string,reason:string){return(await dbPool.query(`UPDATE recycling_daily_closures SET status='reopened',reopened_by=$3::uuid,reopened_at=now(),reopen_reason=$4,updated_at=now() WHERE id=$1::uuid AND organization_id=$2::uuid AND status='closed' RETURNING *`,[id,org,user,reason])).rows[0]??null}

export async function assertPurchaseFunding(org:string,d:any){
 const total=d.quantityKg*d.unitPurchasePriceUgx+d.workerWagesUgx+d.foodUgx+d.transportUgx+d.driverFeeUgx+d.otherExpenseUgx;
 const state=(await dbPool.query(`SELECT organization_cash_position($1::uuid)::bigint cash,organization_available_to_commit($1::uuid)::bigint available,EXISTS(SELECT 1 FROM organization_finance_settings WHERE organization_id=$1::uuid) opening_balance_configured,COALESCE((SELECT SUM(CASE WHEN transaction_type='given' THEN amount_ugx ELSE -amount_ugx END) FROM recycling_manager_float_transactions WHERE organization_id=$1::uuid),0)::bigint float_balance`,[org])).rows[0];
 if(d.purchasePaymentStatus==='paid'&&!state.opening_balance_configured)throw financeError('Company funding has not been initialized. Ask the company administrator to set the verified opening balance under Finance before recording a paid purchase.');
 const officeCash=Number(state.cash)-Number(state.float_balance),officeRequired=total-d.managerFloatUsedUgx;
 if(d.purchasePaymentStatus==='paid'&&officeRequired>officeCash)throw financeError(`Purchase needs ${officeRequired.toLocaleString()} UGX from office cash, but only ${Math.max(officeCash,0).toLocaleString()} UGX is available after manager float.`)
 if(d.purchasePaymentStatus==='credit'&&total>Number(state.available)){const available=Number(state.available);throw financeError(available<0?`Credit purchase cannot be committed. Available funds are UGX 0 and existing commitments exceed cash by UGX ${Math.abs(available).toLocaleString()}.`:`Credit purchase cannot be committed. Only UGX ${available.toLocaleString()} is available.`)}
 if(d.purchasePaymentStatus==='credit'&&d.managerFloatUsedUgx>0)throw financeError('A credit purchase cannot use manager float before it is paid.');
 if(d.managerFloatUsedUgx>Number(state.float_balance))throw financeError(`Only ${Math.max(Number(state.float_balance),0).toLocaleString()} UGX is left in the manager float and this needs ${Number(d.managerFloatUsedUgx).toLocaleString()} UGX. Ask the office to issue more float.`);
}
export async function assertCashFunding(org:string,amount:number,label:string){
 if(amount<=0)return;
 const state=(await dbPool.query(`SELECT organization_cash_position($1::uuid)::bigint cash,COALESCE((SELECT SUM(CASE WHEN transaction_type='given' THEN amount_ugx ELSE -amount_ugx END) FROM recycling_manager_float_transactions WHERE organization_id=$1::uuid),0)::bigint float_balance`,[org])).rows[0],cash=Number(state.cash)-Number(state.float_balance);
 if(amount>cash)throw financeError(`${label} cannot be paid: ${amount.toLocaleString()} UGX is required but only ${cash.toLocaleString()} UGX cash is available.`);
}
export async function assertFloatFunding(org:string,d:any){
 const state=(await dbPool.query(`SELECT organization_cash_position($1::uuid)::bigint cash,EXISTS(SELECT 1 FROM organization_finance_settings WHERE organization_id=$1::uuid) opening_balance_configured,COALESCE((SELECT SUM(CASE WHEN transaction_type='given' THEN amount_ugx ELSE -amount_ugx END) FROM recycling_manager_float_transactions WHERE organization_id=$1::uuid),0)::bigint float_balance`,[org])).rows[0],cash=Number(state.cash),balance=Number(state.float_balance);
 if(d.transactionType==='given'&&!state.opening_balance_configured)throw financeError('Company funding has not been initialized. Ask the company administrator to set the verified opening balance under Finance before allocating employee float.');
 if(d.transactionType==='given'&&balance+d.amountUgx>cash)throw financeError(`Float allocation exceeds available cash. Cash is ${cash.toLocaleString()} UGX and ${balance.toLocaleString()} UGX is already allocated.`);
 if(d.transactionType==='spent'&&(d.amountUgx>balance||d.amountUgx>cash))throw financeError(`Float spending is unavailable. Float balance is ${balance.toLocaleString()} UGX and cash balance is ${cash.toLocaleString()} UGX.`);
}
export async function assertCreditPurchasePaymentFunding(org:string,amount:number){
 await assertCashFunding(org,amount,'Supplier payment');
}
